import Foundation

/// Registrable-domain lookup (the "eTLD+1") backed by the Public Suffix List.
/// `Resources/public_suffix_list.dat` is generated by `scripts/update-public-suffix-list.sh`.
struct PublicSuffixList: Sendable {
    private var rules: Set<String> = []
    private var wildcards: Set<String> = []
    private var exceptions: Set<String> = []

    /// One rule per line: `example.com`, `*.example.com` or `!www.example.com`.
    init(contents: String) {
        for line in contents.split(whereSeparator: \.isNewline) {
            let rule = line.trimmingCharacters(in: .whitespaces)
            if rule.isEmpty { continue }
            if rule.hasPrefix("!") {
                exceptions.insert(String(rule.dropFirst()))
            } else if rule.hasPrefix("*.") {
                wildcards.insert(String(rule.dropFirst(2)))
            } else {
                rules.insert(rule)
            }
        }
    }

    private final class BundleToken {}

    static let shared: PublicSuffixList = {
        let url = Bundle(for: BundleToken.self).url(forResource: "public_suffix_list", withExtension: "dat")
        let contents = url.flatMap { try? String(contentsOf: $0, encoding: .utf8) } ?? ""
        return PublicSuffixList(contents: contents)
    }()

    /// The registrable domain of `host` (e.g. `bbc.co.uk` for `www.bbc.co.uk`), or nil when `host`
    /// is itself a public suffix.
    func registrableDomain(of host: String) -> String? {
        let labels = host.lowercased().split(separator: ".", omittingEmptySubsequences: false).map(String.init)
        let count = labels.count
        guard count > 0, !labels.contains("") else { return nil }

        var suffixLength = 1 // the implicit "*" rule: an unlisted TLD is its own suffix
        for i in 0..<count {
            if exceptions.contains(labels[i...].joined(separator: ".")) {
                // An exception rule is never a suffix itself; its parent is.
                return domain(labels, suffixLength: count - i - 1)
            }
            if rules.contains(labels[i...].joined(separator: ".")) {
                suffixLength = max(suffixLength, count - i)
            }
            if i + 1 < count, wildcards.contains(labels[(i + 1)...].joined(separator: ".")) {
                suffixLength = max(suffixLength, count - i)
            }
        }
        return domain(labels, suffixLength: suffixLength)
    }

    private func domain(_ labels: [String], suffixLength: Int) -> String? {
        guard suffixLength < labels.count else { return nil }
        return labels[(labels.count - suffixLength - 1)...].joined(separator: ".")
    }
}
